import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Update Workspace Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-14-update-workspace-profile/sequence-flow.md","filePath":"feature/agency-workspace/3-4-14-update-workspace-profile/sequence-flow.md"}'),i={name:"feature/agency-workspace/3-4-14-update-workspace-profile/sequence-flow.md"};function r(l,e,d,n,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="sequence-flow-—-update-workspace-profile" tabindex="-1">Sequence Flow — Update Workspace Profile <a class="header-anchor" href="#sequence-flow-—-update-workspace-profile" aria-label="Permalink to &quot;Sequence Flow — Update Workspace Profile&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.14). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — the MANAGER of the Workspace.</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding Workspace records.</li><li><strong>File storage</strong> — the external store holding the uploaded Workspace logo.</li></ul><hr><h2 id="flow-a-—-update-settings-and-workspace-details" tabindex="-1">Flow A — Update settings and Workspace details <a class="header-anchor" href="#flow-a-—-update-settings-and-workspace-details" aria-label="Permalink to &quot;Flow A — Update settings and Workspace details&quot;">​</a></h2><ol><li>Client → System: on <code>/workspaces/:id/settings</code>, edit the name, timezone, default platforms, report frequency, industry, company size, website, phone, or location and submit.</li><li>System: check the caller&#39;s role in the Workspace before handling the request — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System → Database: look up the Workspace by its identifier; a missing Workspace is rejected with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System: apply the supplied name when it is not blank.</li><li>System: parse the stored settings and merge in the new timezone and default platforms, keeping the previous values for fields left out of the request.</li><li>System: store the merged settings and apply the supplied industry, company size, website, phone, and location.</li><li>System: record the update timestamp.</li><li>System → Database: write the updated Workspace.</li><li>System → Client: the updated Workspace profile.</li><li>Client: show a success confirmation and refresh the profile.</li></ol><h2 id="flow-b-—-update-the-workspace-logo" tabindex="-1">Flow B — Update the Workspace logo <a class="header-anchor" href="#flow-b-—-update-the-workspace-logo" aria-label="Permalink to &quot;Flow B — Update the Workspace logo&quot;">​</a></h2><ol><li>Client → System: choose a logo image file; the client rejects it up front if it is not image/jpeg, image/png, or image/webp, or if it exceeds 5 MB, before any request is sent.</li><li>System: check the caller&#39;s role — a caller who is not the Workspace MANAGER is rejected with 403 <code>FORBIDDEN</code>.</li><li>System → Database: look up the Workspace by its identifier; a missing Workspace is rejected with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System: read the uploaded file&#39;s bytes; a read failure is rejected with 400 <code>FILE_READ_ERROR</code>.</li><li>System → File storage: upload the logo and receive its location.</li><li>System: set the Workspace logo location and record the update timestamp.</li><li>System → Database: write the updated Workspace.</li><li>System → Client: the updated Workspace profile carrying the new logo location.</li><li>Client: display the new logo.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>Update settings / Upload logo</td><td>Caller is not the MANAGER of that Workspace</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Update settings / Upload logo</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>Upload logo</td><td>The uploaded file cannot be read</td><td>400</td><td><code>FILE_READ_ERROR</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The role check is applied before the request reaches the update handling, so a non-MANAGER never triggers a Workspace lookup.</li><li>Fields omitted from the request keep their current values; the settings payload is merged rather than replaced.</li><li>The logo has its own dedicated action, separate from the settings update.</li></ul>',14)])])}const f=t(i,[["render",r]]);export{u as __pageData,f as default};
